// 99% of calls pass a List<int> here.
// Without a profile every foreach step is an interface call;
// with a profile Tier 1 builds a fast path for List<int>.
static int Sum(IEnumerable<int> items)
{
    int s = 0;
    foreach (var x in items) s += x;
    return s;
}

